import boto3, json, os, time
sqs = boto3.client("sqs")
def handler(event, context):
    def audit(phase, **extra):
        record = dict(phase=phase, event=event, runtime_request_id=context.aws_request_id,
                      invoked_function_arn=context.invoked_function_arn,
                      function_version=context.function_version, runtime_time_ms=int(time.time()*1000), **extra)
        sqs.send_message(QueueUrl=os.environ["AUDIT_QUEUE_URL"], MessageBody=json.dumps(record))
        print(json.dumps(record))
    audit("entered")
    released = False
    if event.get("hold"):
        deadline = time.monotonic() + 170
        while time.monotonic() < deadline:
            messages = sqs.receive_message(QueueUrl=os.environ["RELEASE_QUEUE_URL"], WaitTimeSeconds=2, MaxNumberOfMessages=1).get("Messages", [])
            for message in messages:
                signal = json.loads(message["Body"])
                sqs.delete_message(QueueUrl=os.environ["RELEASE_QUEUE_URL"], ReceiptHandle=message["ReceiptHandle"])
                if signal.get("label") == event["label"]:
                    released = True
                    break
            if released:
                break
        audit("exiting", released=released)
        if not released:
            raise TimeoutError("owned release signal not received before bounded timeout")
    else:
        audit("exiting", released=False)
    return {"label": event["label"], "ok": True, "released": released}
